pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    B c;
    function setUp() public { c = new B(); }

    function testFuzz_property(uint256 amount, bool targetReverts) public {
        amount = bound(amount, 0, 1 ether);

        ReverterOrAccepter helper = new ReverterOrAccepter(targetReverts);

        vm.deal(address(this), 2 ether);

        address caller = address(uint160(uint256(keccak256(abi.encodePacked(amount, targetReverts, block.timestamp)))));
        vm.deal(caller, 1 ether);

        payable(address(c)).transfer(0.5 ether);

        uint256 ownerBefore = address(this).balance;

        vm.prank(caller);
        bool ok;
        try c.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(this).balance > ownerBefore);
        } else {
            assertTrue(address(c).balance >= 0);
        }
    }
}

contract ReverterOrAccepter {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable { shouldRevert = _shouldRevert; }
    receive() external payable {
        if (shouldRevert) revert();
    }
    fallback() external payable {
        if (shouldRevert) revert();
    }
}
